class EmbedAsymmetricTensorFieldEigenvectorPartition(Node):
    def __init__(self, parent_node_id : str, resolution : int = 16):
        super().__init__(parent_node_id, AsymmetricTensor, EigenvectorPartitionEmbedding, locals())

        self.resolution = resolution

    @classmethod
    def guardrails(cls):
        return [
            Guardrail(
                get_prompt("guardrails", "eigenvector_partition_degenerate_points"),
                "degenerate_points_are_also_embedded",
                "Set to True if degenerate points will be separately computed and visualized. Set to False otherwise.",
                raise_on_tool_param_false(
                    "Cannot create this node because visualizing the eigenvector partition also requires separately "
                    "computing and visualizing the degenerate points."
                ),
            ),
            _visualize_alongside_descriptors_guardrail
        ]

    @classmethod
    def chat_description(cls):
        return "queued embedding asymmetric tensor field eigenvector partition"

    @classmethod
    def description(cls):
        from topopilot.config import correctness_checks_on

        desc = 'Creates a geometric embedding of a node of type asymmetric_tensor. It will display the ' \
               'eigenvector partition. It partitions the domain according to whether rotation or ' \
               'anisotropic stretching is stronger as well as the direction of rotation.'

        if not correctness_checks_on():
            desc += "This function does not compute the degenerate points, yet the degenerate points are part of the eigenvector "\
                    "partition. Thus, when visualizing the eigenvector partition, also separately compute and visualize "\
                    "the degenerate points using a separate function."

        return desc

    @classmethod
    def param_descriptions(cls):
        return {'parent_node_id': 'The id of a node of type asymmetric_tensor that should be '
                           'embedded.',
         'resolution': 'How many times should each grid cell be subdivided when displaying the '
                       'partition. Higher values are more computationally expensive but lead '
                       'to better visual results.'}

    def compatible_to_visualize(self, other):
        if issubclass(other.node_type, SquareOrCubeEmbedding):
            return False, f"Cannot embed a node of type {self.node_type.get_mcp_name()} along with another "\
                          f"of type {other.node_type.get_mcp_name()}. They will overlap in the visualization"

        return True, ""

    def _evaluation_logic(self, parent_data, time_step):

        f = servermanager.Fetch(parent_data.data)

        array = paraview_vti_to_numpy(parent_data.data)
        partition_array = eigenvector_partition(array, self.resolution)
        dimensions = servermanager.Fetch(parent_data.data).GetDimensions()

        return EigenvectorPartitionEmbedding(numpy_to_paraview_vti(partition_array, self.resolution), dimensions)

